trait Speak {
    fn speak(&self) -> String;
}

struct Dog;
struct Cat;

impl Speak for Dog {
    fn speak(&self) -> String {
        String::from("Woof")
    }
}

impl Speak for Cat {
    fn speak(&self) -> String {
        String::from("Meow")
    }
}

fn main() {
    let pets: Vec<Box<dyn Speak>> = vec![Box::new(Dog), Box::new(Cat)];
    for p in &pets {
        println!("{}", p.speak());
    }
}

trait Area {
    fn area(&self) -> u32;
}

struct Sq(u32);
struct Rect(u32, u32);

impl Area for Sq {
    fn area(&self) -> u32 {
        self.0 * self.0
    }
}

impl Area for Rect {
    fn area(&self) -> u32 {
        self.0 * self.1
    }
}

fn show(x: &dyn Area) {
    println!("{}", x.area());
}

fn main() {
    show(&Sq(4));
    show(&Rect(2, 5));
}

trait Shape {
    fn area(&self) -> f64;
}

struct Sq(f64);

impl Shape for Sq {
    fn area(&self) -> f64 {
        self.0 * self.0
    }
}

fn main() {
    let shapes: Vec<dyn Shape> = Vec::new();
    println!("{}", shapes.len());
}

trait Score {
    fn points(&self) -> i32;
}

struct Goal;
struct Penalty;

impl Score for Goal {
    fn points(&self) -> i32 {
        3
    }
}

impl Score for Penalty {
    fn points(&self) -> i32 {
        -1
    }
}

fn main() {
    let events: Vec<Box<dyn Score>> = vec![
        Box::new(Goal),
        Box::new(Penalty),
        Box::new(Goal),
    ];
    let total: i32 = events.iter().map(|e| e.points()).sum();
    println!("{total}");
}

trait Op {
    fn apply(&self, x: i32) -> i32;
}

struct Add(i32);
struct Mul(i32);

impl Op for Add {
    fn apply(&self, x: i32) -> i32 {
        x + self.0
    }
}

impl Op for Mul {
    fn apply(&self, x: i32) -> i32 {
        x * self.0
    }
}

fn main() {
    let pipeline: Vec<Box<dyn Op>> = vec![
        Box::new(Add(2)),
        Box::new(Mul(5)),
        Box::new(Add(1)),
    ];
    let mut v = 3;
    for op in &pipeline {
        v = op.apply(v);
    }
    println!("{v}");
}
